     and ncl.inspection_id = #{inspectionId}
     and ncl.inspection_service_id = #{inspectionServiceId}
     and ncl.inspection_content_id = #{inspectionContentId}
     and ncl.pm_id = #{pmId}
     and ncl.swc_job_content_id = #{swcJobContentId}
     and ncl.swc_job_content_str = #{swcJobContentStr}
     and ncl.pm_group_id = #{pmGroupId}
     and ncl.pm_group_item_id = #{pmGroupItemId}
     and ncl.inspection_content_str = #{inspectionContentStr}
     and ncl.pm_group_item_str = #{pmGroupItemStr}
