     and ncl.check_user_name = #{checkUserName}
     and ncl.check_user_id = #{checkUserId}
     and ncl.check_content = #{checkContent}
     and ncl.files = #{files}
     and ncl.check_project_id = #{checkProjectId}
     and ncl.facility_number like concat('%', #{facilityNumber}, '%')

        and ncl.create_time between #{params.startTime} and #{params.endTime}


